#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define pii pair<int, int>
#define F first
#define S second

inline void Fread(int& x) {
    x = 0;
    char c = getchar();
    int sign = 1;
    while (c < '0' || c > '9') {
        if (c == '-') sign = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = (x << 3) + (x << 1) + (c - '0');
        c = getchar();
    }
    x *= sign;
}

inline void Fout(int x, char e = '\n') {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    if (x >= 10) Fout(x / 10);
    putchar(x % 10 + '0');
    if (e != '\0') putchar(e);
}

const int MAXN = 505;
int N, M, MOD;
int fac[MAXN], inv[MAXN], F[MAXN], G[MAXN];
int d1[MAXN][MAXN][2], d2[MAXN][MAXN][2];

inline int mod_add(int a, int b) {
    a += b;
    return a >= MOD ? a - MOD : a;
}

inline int mod_sub(int a, int b) {
    a -= b;
    return a < 0 ? a + MOD : a;
}

inline int mod_mul(ll a, int b) {
    return (int)(a * b % MOD);
}

inline int mod_pow(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = mod_mul(res, base);
        base = mod_mul(base, base);
        exp >>= 1;
    }
    return res;
}

inline int comb(int n, int k) {
    return mod_mul((ll)fac[n], (ll)inv[k] * inv[n - k] % MOD);
}

int main() {
    Fread(N); Fread(M); Fread(MOD);

    fac[0] = 1;
    for (int i = 1; i <= N; ++i)
        fac[i] = mod_mul(fac[i - 1], i);

    inv[N] = mod_pow(fac[N], MOD - 2);
    for (int i = N; i >= 1; --i)
        inv[i - 1] = mod_mul(inv[i], i);

    F[0] = 0; G[0] = 1;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= i; ++j) {
            int cur = mod_mul(comb(i - 1, j - 1), i + 1);
            G[i] = mod_add(G[i], mod_mul((ll)G[j - 1] * G[i - j] % MOD, cur));
            F[i] = mod_add(F[i], mod_mul((ll)F[j - 1] * G[i - j] % MOD, cur));
            F[i] = mod_add(F[i], mod_mul((ll)G[j - 1] * F[i - j] % MOD, cur));
            int pt = (j - 1) * j / 2 + (i - j) * (i - j + 1) / 2;
            F[i] = mod_add(F[i], mod_mul((ll)comb(i - 1, j - 1) * (ll)G[j - 1] % MOD * G[i - j] % MOD, pt));
        }
    }

    d1[0][0][1] = 0;
    d2[0][0][1] = 1;
    for (int i = 1; i <= N; ++i) {
        for (int j = 0; j <= i; ++j) {
            d1[i][j][1] = mod_add(d1[i - 1][j][0], d1[i - 1][j][1]);
            d2[i][j][1] = mod_add(d2[i - 1][j][0], d2[i - 1][j][1]);
            for (int k = 1; k <= j; ++k) {
                int c = comb(j, k);
                d1[i][j][0] = mod_add(d1[i][j][0], mod_mul((ll)c * d2[i - k][j - k][1] % MOD, F[k]));
                d1[i][j][0] = mod_add(d1[i][j][0], mod_mul((ll)c * d1[i - k][j - k][1] % MOD, G[k]));
                d2[i][j][0] = mod_add(d2[i][j][0], mod_mul((ll)c * d2[i - k][j - k][1] % MOD, G[k]));
            }
        }
    }

    Fout(mod_add(d1[N][M][0], d1[N][M][1]));
    return 0;
}
